  margin: 0;
  padding: 0;
}

#app {
  font-family: Avenir, Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-align: center;
  color: #2c3e50;
  margin-top: 0;
}

/* App.vue 전역 스타일 섹션에 추가 */
.floating-nav-bar {
  position: fixed;
  bottom: 25px;
  left: 50%;
  transform: translateX(-50%);
  width: 90%;
  max-width: 450px;
  background-color: rgba(255, 255, 255, 0.98);
  display: flex;
  justify-content: space-around;
  align-items: center;
  padding: 12px 10px;
  border-radius: 50px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
  z-index: 5000; /* 최상단 고정 */
  border: 1px solid #efefef;
}
.nav-item { display: flex; flex-direction: column; align-items: center; flex: 1; cursor: pointer; transition: 0.2s; }
.nav-item.active .material-icons, .nav-item.active .nav-text { color: #2196F3; }
.material-icons { font-size: 24px; color: #444; margin-bottom: 2px; }
.nav-text { font-size: 10px; color: #666; font-weight: 600; }

/* --- 연도·달 이동 창 --- */
.picker-overlay {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: rgba(0, 0, 0, 0.45);
  display: flex; align-items: center; justify-content: center;
  z-index: 6500; /* 하단바(5000)보다 위 */
}
.picker-modal {
  background: #fff; border-radius: 16px; padding: 22px 20px 18px;
  width: 86%; max-width: 360px; box-sizing: border-box;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.2);
}
.picker-title { margin: 0 0 14px; font-size: 1.1rem; color: #333; text-align: center; }
.picker-year { display: flex; align-items: center; justify-content: center; gap: 16px; margin-bottom: 14px; }
.year-btn {
  width: 36px; height: 36px; border-radius: 50%; border: 1px solid #ddd; background: #f5f5f5;
  color: #555; font-size: 1.2rem; cursor: pointer; display: flex; align-items: center; justify-content: center;
}
.year-text { font-size: 1.25rem; font-weight: bold; color: #222; min-width: 80px; text-align: center; }
.picker-months { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 18px; }
.month-btn {
  height: 40px; border-radius: 8px; border: 1px solid #e0e0e0; background: #fff;
  color: #333; font-size: 0.9rem; cursor: pointer;
}
.month-btn.selected { background: #2196F3; color: #fff; border-color: #2196F3; font-weight: bold; }
.month-btn.current { border-color: #ec2525; }
.picker-actions { display: flex; gap: 8px; }
.picker-actions button { flex: 1; height: 44px; border-radius: 10px; border: none; font-size: 0.95rem; font-weight: bold; cursor: pointer; }
.picker-cancel { background: #eceff1; color: #555; }
.picker-ok { background: #2196F3; color: #fff; }
</style>
