<template>
  <div class="sub-page-overlay" ref="overlay">
    <div class="sub-page-container">
      <div class="list-header">
        <h2 class="list-title">{{ titleText }}</h2>
      </div>

      <div class="filter-row">
        <span class="filter-desc">날짜순 목록</span>
        <div class="filter-chips">
          <button class="chip" :class="{ on: !onlyMe }" @click="onlyMe = false">전체</button>
          <button class="chip" :class="{ on: onlyMe }" @click="onlyMe = true">내 당직만</button>
        </div>
      </div>

      <div v-for="month in months" :key="month.key" class="month-block">
        <div class="month-label">{{ month.label }}</div>

        <div v-if="month.rows.length === 0" class="empty-row">
          {{ onlyMe ? '이 달에는 내 당직이 없습니다.' : '날짜가 없습니다.' }}
        </div>

        <div
          v-for="row in month.rows"
          :key="row.dateKey"
          class="list-row"
          :class="{ 'is-me': row.isMe, 'is-today': row.isToday }"
        >
          <span class="row-date" :class="{ sun: row.dow === 0, sat: row.dow === 6 }">
            {{ row.dateLabel }}
          </span>
          <span class="row-name" :class="{ empty: !row.name }">{{ row.name || '—' }}</span>
          <span v-if="row.isToday" class="today-badge">오늘</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
const MONTHS_TO_SHOW = 3;
const WEEK_NAMES = ['일', '월', '화', '수', '목', '금', '토'];

export default {
  name: 'ListPage',
  props: {
    dutyData: { type: Array, default: () => [] },
    startDate: { type: Date, default: () => new Date() }
  },
  data() {
    return {
      onlyMe: false
    };
  },
  computed: {
    titleText() {
      return `${this.startDate.getFullYear()}년 ${this.startDate.getMonth() + 1}월~`;
    },
    // 날짜 키(YYMMDD) → 당직 정보
    dutyMap() {
      const map = {};
      (this.dutyData || []).forEach(p => {
        if (p.category === '당직') map[String(p.date)] = p;
      });
      return map;
    },
    months() {
      const today = new Date();
      const baseY = this.startDate.getFullYear();
      const baseM = this.startDate.getMonth();
      const result = [];

      for (let k = 0; k < MONTHS_TO_SHOW; k++) {
        const first = new Date(baseY, baseM + k, 1);
        const y = first.getFullYear();
        const m = first.getMonth();
        const lastDay = new Date(y, m + 1, 0).getDate();
        const rows = [];

        for (let d = 1; d <= lastDay; d++) {
          const dateKey = `${String(y).slice(-2)}${String(m + 1).padStart(2, '0')}${String(d).padStart(2, '0')}`;
          const duty = this.dutyMap[dateKey];
          const isMe = !!duty && duty.meYn === 'Y';
          if (this.onlyMe && !isMe) continue;

          const dow = new Date(y, m, d).getDay();
          rows.push({
            dateKey,
            dateLabel: `${m + 1}/${d} (${WEEK_NAMES[dow]})`,
            dow,
            name: duty ? duty.name : '',
            isMe,
            isToday: y === today.getFullYear() && m === today.getMonth() && d === today.getDate()
          });
        }

        result.push({ key: `${y}-${m}`, label: `${y}년 ${m + 1}월`, rows });
      }
      return result;
    }
  },
  mounted() {
    // 오늘이 목록 안에 있으면 그 줄이 보이도록 스크롤
    this.$nextTick(() => {
      const el = this.$refs.overlay && this.$refs.overlay.querySelector('.is-today');
      if (el && el.scrollIntoView) el.scrollIntoView({ block: 'center' });
    });
  }
};
</script>

